import {result,outputText,e,n,download,linkDownload,error} from '../ui.mjs';
import {jsonCSV} from '../extra-core.mjs';
import {dateUTC} from '../core.mjs';
export const need=(condition,message)=>{if(!condition)throw Error(message);};
export const optional=f=>({...f,required:false});
export const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
export const localNow=()=>{const d=new Date();return today()+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');};
export const dayDiff=(a,b)=>Math.round((dateUTC(b)-dateUTC(a))/86400000);
export const table=(headers,rows)=>`<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(x=>`<th scope="col">${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${e(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export function exportCSV(out,rows,name='nepocore-data.csv'){const b=document.createElement('button');b.type='button';b.className='btn secondary small';b.textContent='Download CSV';(out.querySelector('.result-actions')||out).append(b);linkDownload(b,new Blob([jsonCSV(rows).text],{type:'text/csv;charset=utf-8'}),name);}
export function plainResult(out,value,details=[],label){result(out,{label,value,details,copy:String(value)});}
export function fileResult(out,blob,name,{html='',details=[],image=false}={}){result(out,{html:html+(image?'<div class="image-preview"><img alt="Created result"></div>':'')+'<div class="result-actions"><button class="btn primary" data-save>Download '+(image?'image':'file')+'</button></div>',details});const release=linkDownload(out.querySelector('[data-save]'),blob,name),a=out.querySelector('a[download]');if(image)out.querySelector('img').src=a.href;return release;}
export function textFile(out,value,name,type='text/plain'){outputText(out,value);const b=document.createElement('button');b.className='btn secondary small';b.textContent='Download '+name;out.querySelector('.result-actions').append(b);linkDownload(b,new Blob([value],{type}),name);}
export function localChoice(mount,key,read,write){const label=document.createElement('label');label.className='save-choice';label.innerHTML='<input type="checkbox"> Save on this device';const input=label.querySelector('input');try{const v=localStorage.getItem(key);if(v){read(JSON.parse(v));input.checked=true;}}catch{}input.onchange=()=>{try{if(input.checked)localStorage.setItem(key,JSON.stringify(write()));else localStorage.removeItem(key);}catch{error(mount,'Local saving is unavailable. You can still export your session.');}};mount.append(label);return()=>{try{if(input.checked)localStorage.setItem(key,JSON.stringify(write()));}catch{}};}
export function timerDisplay(seconds){seconds=Math.max(0,seconds);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;}
export function printTools(out,body,title){
 const doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+e(title)+'</title><style>body{font:14px/1.6 Arial,sans-serif;color:#182e29;max-width:760px;margin:35px auto;padding:0 20px}h1{font-size:30px;line-height:1.2}h2{font-size:15px;border-bottom:1px solid #ccd9d1;padding-top:14px}p{white-space:pre-wrap}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:8px;border-bottom:1px solid #dde5df}.doc-top{display:flex;justify-content:space-between;gap:20px}.doc-muted{color:#55655e;font-size:12px}.doc-total{text-align:right;font-size:18px}a{color:inherit}*{overflow-wrap:anywhere}@media print{body{margin:0;max-width:none;padding:0}a{text-decoration:none}@page{size:A4;margin:18mm}}</style></head><body>'+body+'</body></html>';
 const copy=document.createElement('div');copy.innerHTML=body;result(out,{html:'<div class="document-preview">'+body+'</div>',copy:copy.textContent});
 const actions=out.querySelector('.result-actions'),print=document.createElement('button');print.className='btn primary small';print.textContent='Print / Save PDF';let frame;
 print.onclick=()=>{frame?.remove();frame=document.createElement('iframe');frame.className='print-frame';frame.setAttribute('title','Printable '+title);frame.srcdoc=doc;frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();};document.body.append(frame);};actions.append(print);
 const html=document.createElement('button');html.className='btn secondary small';html.textContent='Download HTML';actions.append(html);linkDownload(html,new Blob([doc],{type:'text/html'}),'nepocore-'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.html');return()=>frame?.remove();
}
